import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import "./styles.css";

function App() {
  const [budget, setBudget] = useState("");
  const [predicted, setPredicted] = useState(null);
  const [data, setData] = useState([]);
  const [error, setError] = useState("");

  const handlePredict = async () => {
    if (!budget) {
      setError("Please enter a budget amount");
      return;
    }
    setError("");
    setPredicted(null);

    try {
      const res = await fetch(`http://127.0.0.1:5000/prediction/${budget}`);
      const result = await res.json();
      setPredicted(result);
    } catch (err) {
      setError("Error fetching prediction");
    }
  };

  useEffect(() => {
    const fetchData = async () => {
      try {
        const res = await fetch("http://127.0.0.1:5000/api");
        const raw = await res.json();
        const parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
        setData(parsed);
      } catch (err) {
        console.error(err);
      }
    };
    fetchData();
  }, []);

  return (
    <div>
      {/* Navbar */}
      <nav className="navbar navbar-dark bg-dark shadow-sm">
        <div className="container">
          <span className="navbar-brand">BI Insights Inc</span>
        </div>
      </nav>

      {/* Input Section */}
      <header className="hero-section text-center py-5">
        <div className="container">
          <h2 className="mb-4">Predict Sales from Budget</h2>
          <div className="d-flex justify-content-center">
            <input
              type="number"
              className="form-control w-25 mr-2"
              placeholder="Enter Budget"
              value={budget}
              onChange={(e) => setBudget(e.target.value)}
            />
            <button className="btn btn-primary" onClick={handlePredict}>
              Predict
            </button>
          </div>
          {error && <p className="text-danger mt-2">{error}</p>}
        </div>
      </header>

      {/* Results Section */}
      <section className="bg-light py-5">
        <div className="container text-center">
          <div className="row">
            <div className="col-md-4 mb-3">
              <div className="card shadow-sm p-3">
                <h5>Budget Amount</h5>
                <p className="lead">{budget ? `${budget}K` : "-"}</p>
              </div>
            </div>
            <div className="col-md-4 mb-3">
              <div className="card shadow-sm p-3">
                <h5>Predicted Value</h5>
                <p className="lead">{predicted ? `${predicted}M` : "-"}</p>
              </div>
            </div>
            <div className="col-md-4 mb-3">
              <div className="card shadow-sm p-3">
                <h5>API Status</h5>
                <p className="lead">{budget ? "Flask API Call" : "-"}</p>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Data Table */}
      <div className="container my-5">
        <h4 className="mb-3 text-center">Data Used for Model</h4>
        <table className="table table-striped table-hover shadow-sm">
          <thead className="thead-dark">
            <tr>
              <th>Budget</th>
              <th>Sales</th>
            </tr>
          </thead>
          <tbody>
            {data.map((row, idx) => (
              <tr key={idx}>
                <td>{row.budget}</td>
                <td>{row.sale}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Footer */}
      <footer className="footer bg-dark text-light py-3">
        <div className="container text-center">
          <p className="mb-0">© BI Insights Inc 2025. All Rights Reserved.</p>
        </div>
      </footer>
    </div>
  );
}

export default App;
